output_text:
[
  {
    "id": "pedestrian_only_single_file_aisles",
    "text": "Carts must not be taken into single-file shelf corridors between shelves.",
    "abstraction": {
      "state_properties": {
        "single_file_space": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "between_parallel_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_shelf_corridor": {
          "and": [
            "single_file_space",
            "between_parallel_shelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_corridor"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "An agent may not move into a single-file shelf corridor while holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "single_file_space": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "between_parallel_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_shelf_corridor": {
          "and": [
            "single_file_space",
            "between_parallel_shelves"
          ]
        }
      },
      "events": {
        "enter_single_file_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "single_file_shelf_corridor"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_with_cart"
    }
  },
  {
    "id": "cartless_movement_only_for_narrow_excursions",
    "text": "Except at the entrance or at a cart-parking mouth, moving without a cart is permitted only inside the single-file shelf corridor.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_area": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cart_parking_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "single_file_shelf_corridor": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartless_allowed_area": {
          "or": [
            "entrance_cart_area",
            "cart_parking_mouth",
            "single_file_shelf_corridor"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartless_allowed_area"
          }
        ]
      }
    }
  },
  {
    "id": "drop_cart_only_in_wide_main_aisle",
    "text": "A cart may be set down only in a wide main aisle, not in a shelf bay or constricted passage.",
    "abstraction": {
      "state_properties": {
        "wide_main_aisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "drop_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "drop_cart",
          {
            "not": "wide_main_aisle"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "After parking or releasing a cart, the agent must later retrieve a cart before the trip ends.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "drop_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieve_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "drop_cart",
      "discharge": "retrieve_cart"
    }
  },
  {
    "id": "open_shelf_service_requires_cart",
    "text": "When interacting with shelves from an open or side aisle, the agent should have the cart with them.",
    "abstraction": {
      "state_properties": {
        "open_shelf_service_area": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "open_shelf_service_area",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "single_file_shelf_service_cartless",
    "text": "Shelf interactions inside single-file corridors must be performed without a cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_corridor": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "single_file_shelf_corridor",
          "INTERACT",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "top_shelf_excursion_requires_cart_recovery",
    "text": "After taking an item from the top single-file shelf corridor, the agent must return and recover the cart.",
    "abstraction": {
      "state_properties": {
        "top_single_file_shelf_slot": {
          "and": [
            {
              "or": [
                "at(3,1)",
                "at(6,1)"
              ]
            },
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "top_shelf_pick": {
          "pre": {
            "and": [
              "top_single_file_shelf_slot",
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": null
        },
        "retrieve_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "top_shelf_pick",
      "discharge": "retrieve_cart"
    }
  }
]
